const payload = $json.body || $json;
return [{
  json: {
    workflow_execution_id: $execution.id,
    session_id: (payload.session_id || '').toString(),
    customer_id: (payload.customer_id || '').toString(),
    channel: (payload.channel || 'web').toString(),
    language: ((payload.language || 'es').toString().toLowerCase() === 'en') ? 'en' : 'es',
    priority: (payload.priority || 'normal').toString(),
    reason: (payload.reason || 'Customer requested escalation').toString(),
    conversation_summary: (payload.conversation_summary || '').toString(),
    handoff_required: true,
    handoff_endpoint: (payload.handoff_endpoint || payload.human_inbox_webhook || payload.humanInboxWebhook || '').toString(),
    lead_id: (payload.lead_id || '').toString(),
    customer_name: (payload.customer_name || payload.name || '').toString(),
    customer_email: (payload.email || '').toString(),
    customer_phone: (payload.phone || '').toString(),
    hasInboxEndpoint: Boolean(((payload.handoff_endpoint || payload.human_inbox_webhook || payload.humanInboxWebhook || '').toString().trim().length > 0))
  }
}];

const p = $json;
const source = p.data && typeof p.data === 'object' ? p.data : p;
return [{
  json: {
    handoff_required: true,
    reason: p.reason || source.reason || 'Customer requested escalation',
    priority: p.priority || 'normal',
    conversation_summary: p.conversation_summary || '',
    handoff_status: (source.success === false) ? 'queued_with_warning' : 'queued',
    session_id: p.session_id || '',
    customer_id: p.customer_id || '',
    channel: p.channel || 'web',
    workflow_execution_id: p.workflow_execution_id,
    language: p.language || 'es'
  }
}];

const p = $json;
return [{
  json: {
    handoff_required: true,
    reason: p.reason || 'Human review requested',
    priority: p.priority || 'normal',
    conversation_summary: p.conversation_summary || '',
    handoff_status: 'queued_local',
    session_id: p.session_id || '',
    customer_id: p.customer_id || '',
    channel: p.channel || 'web',
    workflow_execution_id: p.workflow_execution_id,
    language: p.language || 'es'
  }
}];
